window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ae9de7fe2f06cefc"]={"versions": [{"id": "FIG-ae9de7fe2f06cefc", "releases": ["R3.0.7", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Prozess- und Datenflussdiagramm der AUTOSAR-Methodik (Classic Platform) zur Darstellung des Systemkonfigurationsschritts („System Configuration Overview“). Das Diagramm veranschaulicht die Transformation von System-Eingabebeschreibungen und Softwarekomponenten-Implementierungsbeschreibungen in eine konsolidierte Systemkonfigurationsbeschreibung sowie die daraus abgeleitete Kommunikationsmatrix.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivität / Prozessschritt:</strong>\n<ul class=\"fig-list\"><li><code>Configure System</code>: Zentrale Entwurfsaktivität (dargestellt als gelber Prozesspfeil / Chevron).\n</li></ul>\n</li><li><strong>Eingangs-Artefakte (XML-Dateien):</strong>\n<ul class=\"fig-list\"><li><code>System Configuration Input : System</code>: Beschreibung der Topologie, Netzwerke, Software-Komponenten-Prototypen und Anforderungen auf Systemebene.\n</li><li><code>Collection of Available SWC Implementations</code>: Sammlung vorliegender Implementierungsbeschreibungen für Software-Components (SWCs).\n</li></ul>\n</li><li><strong>Ausgangs-Artefakte (XML-Dateien):</strong>\n<ul class=\"fig-list\"><li><code>System Configuration Description : System</code>: Vollständige Systemkonfigurationsbeschreibung inklusive Mapping von Softwarekomponenten auf Steuergeräte (ECUs).\n</li><li><code>System Communication-Matrix : CommunicationMatrixType</code>: Kommunikationsmatrix, die Signale, Frames, PDUs und Cluster-Eigenschaften für die Buskommunikation definiert.\n</li></ul>\n</li><li><strong>Leitlinie / Standard:</strong>\n<ul class=\"fig-list\"><li><code>AUTOSAR</code>: Referenz über eine gestrichelte Linie am unteren Rand als Regelwerk/Methodikvorgabe für die Aktivität.\n</li></ul>\n</li><li><strong>Beziehungen &amp; Abhängigkeiten:</strong>\n<ul class=\"fig-list\"><li>Solide gerichtete Pfeile stellen den Datenfluss von den Eingangsartefakten in die Aktivität <code>Configure System</code> und von dort zu den Ausgangsartefakten dar.\n</li><li>Ein gestrichelter gerichteter Pfeil zwischen <code>System Configuration Description : System</code> und <code>System Communication-Matrix : CommunicationMatrixType</code> kennzeichnet die direkte Abhängigkeit bzw. Ableitung der Kommunikationsmatrix aus der Systemkonfigurationsbeschreibung.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Bereitstellung der Eingangsartefakte <code>System Configuration Input : System</code> und <code>Collection of Available SWC Implementations</code>.\n</li><li>Durchführung der Aktivität <code>Configure System</code>, gesteuert durch die AUTOSAR-Vorgaben:\n<ul class=\"fig-list\"><li>Allokation/Mapping von SWC-Instanzen auf ECUs.\n</li><li>Festlegung von Timing-Anforderungen, Netzwerktopologie und Bus-Parametern.\n</li></ul>\n</li><li>Generierung bzw. Aktualisierung der <code>System Configuration Description : System</code>.\n</li><li>Ableitung und Bereitstellung der <code>System Communication-Matrix : CommunicationMatrixType</code> basierend auf der erstellten Systemkonfigurationsbeschreibung.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Normativ definiert dieser Schritt den Kern des AUTOSAR-Systemdesigns, bei dem logische Softwarearchitektur und Hardwaretopologie zusammengeführt werden.\n</li><li>Die Ausgabedatei <code>System Configuration Description</code> dient als primäre Eingabe für die nachfolgenden Schritte der ECU-Extraktion (<code>Extract ECU System Description</code>) und ECU-Konfiguration.\n</li><li>Für Werkzeugentwickler und Systemintegratoren ist die Konsistenz zwischen der aggregierten Systemkonfiguration und der abgeleiteten Kommunikationsmatrix zwingend sicherzustellen, da Downstream-Generatoren (RTE- und BSW-Generierung) auf exakt übereinstimmende PDU-, Frame- und Signaldefinitionen angewiesen sind.\n</li></ul>"}, {"id": "FIG-6aa3170b41a6862a", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Prozess- und Datenflussdiagramm der AUTOSAR-Methodik (Classic Platform) zur Darstellung des Systemkonfigurationsschritts („System Configuration Overview“). Das Diagramm veranschaulicht die Transformation von System-Eingabebeschreibungen und Softwarekomponenten-Implementierungsbeschreibungen in eine konsolidierte Systemkonfigurationsbeschreibung sowie die daraus abgeleitete Kommunikationsmatrix.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivität / Prozessschritt:</strong>\n<ul class=\"fig-list\"><li><code>Configure System</code>: Zentrale Entwurfsaktivität (dargestellt als gelber Prozesspfeil / Chevron).\n</li></ul>\n</li><li><strong>Eingangs-Artefakte (XML-Dateien):</strong>\n<ul class=\"fig-list\"><li><code>System Configuration Input : System</code>: Beschreibung der Topologie, Netzwerke, Software-Komponenten-Prototypen und Anforderungen auf Systemebene.\n</li><li><code>Collection of Available SWC Implementations</code>: Sammlung vorliegender Implementierungsbeschreibungen für Software-Components (SWCs).\n</li></ul>\n</li><li><strong>Ausgangs-Artefakte (XML-Dateien):</strong>\n<ul class=\"fig-list\"><li><code>System Configuration Description : System</code>: Vollständige Systemkonfigurationsbeschreibung inklusive Mapping von Softwarekomponenten auf Steuergeräte (ECUs).\n</li><li><code>System Communication-Matrix : CommunicationMatrixType</code>: Kommunikationsmatrix, die Signale, Frames, PDUs und Cluster-Eigenschaften für die Buskommunikation definiert.\n</li></ul>\n</li><li><strong>Leitlinie / Standard:</strong>\n<ul class=\"fig-list\"><li><code>AUTOSAR</code>: Referenz über eine gestrichelte Linie am unteren Rand als Regelwerk/Methodikvorgabe für die Aktivität.\n</li></ul>\n</li><li><strong>Beziehungen &amp; Abhängigkeiten:</strong>\n<ul class=\"fig-list\"><li>Solide gerichtete Pfeile stellen den Datenfluss von den Eingangsartefakten in die Aktivität <code>Configure System</code> und von dort zu den Ausgangsartefakten dar.\n</li><li>Ein gestrichelter gerichteter Pfeil zwischen <code>System Configuration Description : System</code> und <code>System Communication-Matrix : CommunicationMatrixType</code> kennzeichnet die direkte Abhängigkeit bzw. Ableitung der Kommunikationsmatrix aus der Systemkonfigurationsbeschreibung.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Bereitstellung der Eingangsartefakte <code>System Configuration Input : System</code> und <code>Collection of Available SWC Implementations</code>.\n</li><li>Durchführung der Aktivität <code>Configure System</code>, gesteuert durch die AUTOSAR-Vorgaben:\n<ul class=\"fig-list\"><li>Allokation/Mapping von SWC-Instanzen auf ECUs.\n</li><li>Festlegung von Timing-Anforderungen, Netzwerktopologie und Bus-Parametern.\n</li></ul>\n</li><li>Generierung bzw. Aktualisierung der <code>System Configuration Description : System</code>.\n</li><li>Ableitung und Bereitstellung der <code>System Communication-Matrix : CommunicationMatrixType</code> basierend auf der erstellten Systemkonfigurationsbeschreibung.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Normativ definiert dieser Schritt den Kern des AUTOSAR-Systemdesigns, bei dem logische Softwarearchitektur und Hardwaretopologie zusammengeführt werden.\n</li><li>Die Ausgabedatei <code>System Configuration Description</code> dient als primäre Eingabe für die nachfolgenden Schritte der ECU-Extraktion (<code>Extract ECU System Description</code>) und ECU-Konfiguration.\n</li><li>Für Werkzeugentwickler und Systemintegratoren ist die Konsistenz zwischen der aggregierten Systemkonfiguration und der abgeleiteten Kommunikationsmatrix zwingend sicherzustellen, da Downstream-Generatoren (RTE- und BSW-Generierung) auf exakt übereinstimmende PDU-, Frame- und Signaldefinitionen angewiesen sind.\n</li></ul>"}], "trans": [{"from": "FIG-ae9de7fe2f06cefc", "to": "FIG-6aa3170b41a6862a", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-6aa3170b41a6862a", "to": "FIG-ae9de7fe2f06cefc", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
